WITH area AS ( SELECT id, place_id, trip_use_count, checkin_count FROM places WHERE ST_DWithin(goroute_point(latitude, longitude), goroute_point(#{latitude}::float8, #{longitude}::float8), #{radiusMeters}::float8) AND visibility_status = 'ACTIVE' AND lifecycle_status = 'ACTIVE'
AND place_group IN
#{placeGroup}
),
activity_places AS ( SELECT ar.id AS place_uuid, a.trip_id FROM area ar JOIN activities a ON a.place_ref_id = ar.id JOIN trips t ON t.id = a.trip_id AND t.is_deleted = FALSE WHERE a.created_at >= NOW() - make_interval(days => #{days}) AND COALESCE(a.status, '') <> 'REJECTED' UNION ALL SELECT ar.id, a.trip_id FROM area ar JOIN activities a ON a.place_ref_id IS NULL AND a.place_id = ar.place_id JOIN trips t ON t.id = a.trip_id AND t.is_deleted = FALSE WHERE a.created_at >= NOW() - make_interval(days => #{days}) AND COALESCE(a.status, '') <> 'REJECTED' UNION ALL SELECT ar.id, a.trip_id FROM area ar JOIN activities a ON a.place_ref_id IS NULL AND a.place_id = ar.id::text JOIN trips t ON t.id = a.trip_id AND t.is_deleted = FALSE WHERE a.created_at >= NOW() - make_interval(days => #{days}) AND COALESCE(a.status, '') <> 'REJECTED' ), trip_uses AS ( SELECT place_uuid, COUNT(DISTINCT trip_id) AS trips FROM activity_places GROUP BY place_uuid ), recent_checkins AS ( SELECT c.place_id AS place_uuid, COUNT(*) AS checkins FROM user_checkins c JOIN area ar ON ar.id = c.place_id WHERE c.is_removed = FALSE AND c.created_at >= NOW() - make_interval(days => #{days}) GROUP BY c.place_id ) SELECT ar.id AS "placeId", COALESCE(tu.trips, 0)::int AS "tripCount", COALESCE(rc.checkins, 0)::int AS "checkinCount" FROM area ar LEFT JOIN trip_uses tu ON tu.place_uuid = ar.id LEFT JOIN recent_checkins rc ON rc.place_uuid = ar.id WHERE tu.trips IS NOT NULL OR rc.checkins IS NOT NULL ORDER BY LN(1 + COALESCE(tu.trips, 0)) + LN(1 + COALESCE(rc.checkins, 0)) DESC, LN(1 + ar.trip_use_count) + LN(1 + ar.checkin_count) DESC, ar.id LIMIT #{limit}

