SELECT 
FROM places

    id > #{afterId}

ORDER BY id
LIMIT #{limit}

WITH activity_places AS ( SELECT a.place_ref_id AS place_uuid, a.trip_id FROM activities a JOIN trips t ON t.id = a.trip_id AND t.is_deleted = FALSE WHERE a.place_ref_id IS NOT NULL AND COALESCE(a.status, '') <> 'REJECTED'
AND a.place_ref_id IN #{placeId}
UNION ALL SELECT p.id, a.trip_id FROM places p JOIN activities a ON a.place_id = p.place_id AND a.place_ref_id IS NULL JOIN trips t ON t.id = a.trip_id AND t.is_deleted = FALSE WHERE COALESCE(a.status, '') <> 'REJECTED'
AND p.id IN #{placeId}
UNION ALL SELECT p.id, a.trip_id FROM places p JOIN activities a ON a.place_id = p.id::text AND a.place_ref_id IS NULL JOIN trips t ON t.id = a.trip_id AND t.is_deleted = FALSE WHERE COALESCE(a.status, '') <> 'REJECTED'
AND p.id IN #{placeId}
), trip_uses AS ( SELECT place_uuid, COUNT(DISTINCT trip_id) AS uses FROM activity_places GROUP BY place_uuid ), checkins AS ( SELECT c.place_id AS place_uuid, COUNT(*) AS checkins FROM user_checkins c WHERE c.is_removed = FALSE AND c.place_id IS NOT NULL
AND c.place_id IN #{placeId}
GROUP BY c.place_id ), counted AS ( SELECT p.id, COALESCE(tu.uses, 0) AS uses, COALESCE(ck.checkins, 0) AS checkins FROM places p LEFT JOIN trip_uses tu ON tu.place_uuid = p.id LEFT JOIN checkins ck ON ck.place_uuid = p.id
WHERE p.id IN #{placeId}
) UPDATE places p SET trip_use_count = counted.uses, checkin_count = counted.checkins FROM counted WHERE counted.id = p.id AND (p.trip_use_count <> counted.uses OR p.checkin_count <> counted.checkins) RETURNING p.id

