SELECT p.id, p.place_id, p.title, p.place_group, p.category, p.sub_types, p.address, p.latitude, p.longitude, p.review_count, p.review_rating, p.ai_description, p.price_range, p.open_hours, p.visit_duration_minutes, p.menu, p.about, CASE WHEN p.attributes -> 'price_level' IS NOT NULL THEN jsonb_build_object('price_level', p.attributes -> 'price_level')::text END AS attributes, p.place_overall_score, p.adjusted_rating, p.thumbnail, p.location_image_id, p.trip_use_count, p.checkin_count, ST_Distance(goroute_point(p.latitude, p.longitude), goroute_point(#{latitude}::float8, #{longitude}::float8)) / 1000.0 AS distance FROM places p WHERE p.visibility_status = 'ACTIVE' AND ST_DWithin(goroute_point(p.latitude, p.longitude), goroute_point(#{latitude}::float8, #{longitude}::float8), #{radiusKm}::float8 * 1000.0)
AND (p.location_image_id = #{areaId} OR (p.location_image_id IS NULL AND ST_DWithin(goroute_point(p.latitude, p.longitude), goroute_point(#{areaLatitude}::float8, #{areaLongitude}::float8), #{areaRadiusKm}::float8 * 1000.0)))
AND p.place_group IN
#{group}
ORDER BY p.place_overall_score DESC NULLS LAST, p.adjusted_rating DESC NULLS LAST, p.review_count DESC NULLS LAST, distance ASC, p.id LIMIT #{limit}
